/* ------------------------------------------------------------------
   Scroll Lines — .bg_line grow-in, scrubbed with random per-line lag
   ------------------------------------------------------------------
   Requires: GSAP + ScrollTrigger

   Webflow setup:
   - Wrap each group of lines in an element with [data-line-scroll]
     (this is the trigger — works with multiple sections per page)
   - Lines keep the .bg_line class

   Behaviour:
   - Every line maps the SAME scroll range to its height:
       0%   when the trigger's top hits the viewport bottom
       100% when the trigger's bottom hits the viewport bottom
   - But each line gets its own randomized catch-up lag, so while
     scrolling they all trail the viewport by different amounts and
     visibly catch up — no fixed order, different feel every load.

   Note: the hero lines are handled by the page loader script and
   are untouched here as long as .section_hero has no
   [data-line-scroll] attribute.
------------------------------------------------------------------- */

function initLineScroll() {

  // ================================================================
  // CONFIG — tweak everything here
  // ================================================================
  const CONFIG = {

    // Per-line catch-up lag, randomized between min and max.
    // The value is roughly "seconds to catch up to the real scroll
    // position": min > 0 means every line always trails at least a
    // little, and the min–max spread is what makes the lines differ
    // from each other. Widen the spread for more chaos, raise both
    // for a heavier, floatier feel.
    lag: {
      min: 1.75,
      max: 5.0,
    },

    // 'none' keeps growth linear with the (lagged) scroll position —
    // the catch-up itself already adds softness, so linear is best
    ease: 'none',

    scrollTrigger: {
      start: 'top bottom', // trigger top hits viewport bottom
      end: 'bottom bottom', // trigger bottom hits viewport bottom
    },
  }
  // ================================================================

  if (typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined') return
  gsap.registerPlugin(ScrollTrigger)

  const sections = gsap.utils.toArray('[data-line-scroll]')
  if (!sections.length) return

  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches

  sections.forEach(section => {
    const lines = gsap.utils.toArray(section.querySelectorAll('.bg_line'))
    if (!lines.length) return

    // Reduced motion: lines are simply always fully grown
    if (reduceMotion) {
      gsap.set(lines, { height: '100%' })
      return
    }

    // One tween + trigger per line, each with its own random lag
    lines.forEach(line => {
      gsap.fromTo(line, {
        height: '0%',
      }, {
        height: '100%',
        ease: CONFIG.ease,
        scrollTrigger: {
          trigger: section,
          start: CONFIG.scrollTrigger.start,
          end: CONFIG.scrollTrigger.end,
          scrub: gsap.utils.random(CONFIG.lag.min, CONFIG.lag.max),
        },
      })
    })
  })
}

initLineScroll();


